import json,sys
seq=1
pending=None
def send(obj):
 global seq
 obj['seq']=seq;seq+=1
 data=json.dumps(obj).encode();sys.stdout.buffer.write(f'Content-Length: {len(data)}\r\n\r\n'.encode()+data);sys.stdout.buffer.flush()
def response(req, body=None): send({'type':'response','request_seq':req['seq'],'success':True,'command':req['command'],'body':body or {}})
def event(name, body=None): send({'type':'event','event':name,'body':body or {}})
while True:
 headers={}
 while True:
  line=sys.stdin.buffer.readline()
  if not line: sys.exit(0)
  if line in (b'\r\n',b'\n'): break
  key,value=line.decode().split(':',1);headers[key.lower()]=value.strip()
 req=json.loads(sys.stdin.buffer.read(int(headers['content-length'])))
 if req.get('type')!='request': continue
 command=req['command']
 if command=='initialize': response(req,{'supportsConfigurationDoneRequest':True})
 elif command=='launch': pending=req;event('initialized')
 elif command=='setBreakpoints': response(req,{'breakpoints':[{'verified':True,'line':x['line']} for x in req['arguments']['breakpoints']]})
 elif command=='configurationDone':
  response(req);response(pending);event('stopped',{'reason':'breakpoint','threadId':1})
 elif command=='stackTrace': response(req,{'stackFrames':[{'id':7,'name':'main','line':3,'column':1,'source':{'path':'sample.py'}}],'totalFrames':1})
 elif command=='disconnect': response(req);sys.exit(0)
 else: response(req)
